 ['전자레인지 위주·전용',/(?:전자레인지|전자렌지|렌지)\s*(?:기능\s*)?(?:만(?!큼)|위주|로만|용으로만|대용)/],
 ['에어프라이어 위주·전용',/(?:에어프라이어|에어프라이기|에프)\s*(?:기능\s*)?(?:만(?!큼)|위주|로만|용으로만|대용)/],
 ['오븐 모드 위주·전용',/오븐\s*(?:모드|기능)\s*(?:만(?!큼)|위주|로만)/],
 ['데우기·해동 위주',/(?:데우는\s*용도|데울\s*때|데우기|해동)\s*(?:만(?!큼)|위주|로만)/],
 ['기능 활용 어려움',/(?:기능|모드|사용법).{0,18}(?:모르겠|어렵|헷갈)|제대로\s*못\s*(?:쓰|써)/],
 ['광파오븐 사용 빈도 낮음',/(?:거의|잘|별로)\s*안\s*(?:쓰|써|사용)|손이\s*안\s*가/]
];
for(const [i,item] of $input.all().entries()){
 const r=requests[i]?.json;if(!r?.row)continue;
 const res=responses[i]?.json||{};
 const body=String(item.json.author||'').replace(/\s+/g,' ').trim();
 const status=Number(res.statusCode);
 const rawDate=String(item.json.published||item.json.visibleDate||'');
 const m=rawDate.match(/(20\d{2})[-./]\s*(\d{1,2})[-./]\s*(\d{1,2})/);
 const d=m?m[1]+'-'+m[2].padStart(2,'0')+'-'+m[3].padStart(2,'0'):'';
 const spans=body.match(/[^.!?。]+/g)||[];
 const evidence=spans.find(s=>/(?:LG|엘지|디오스)\s*(?:디오스\s*)?광파\s*오븐/i.test(s)&&/(?:제가|저는|저희\s*집|우리\s*집|집에서|구매해서|사서|구입해서|구매했|구입했|쓰고\s*있|사용\s*중|사용하고\s*있|쓰다가|써봤)/.test(s)&&/(?:쓰고|쓰다가|씁니다|써요|써봤|사용\s*(?:중|하고|해봤|했)|돌려봤|돌리고|돌려\s*먹)/.test(s)&&!/(?:살\s*예정|구매\s*고민|써보신\s*분|추천\s*해|친구가|지인이|시댁에서|남들은)/.test(s));
 let state='실사용 근거 부족';
 if(status!==200||!body)state='원문 미확보';
 else if(d&&d<earliest)state='기간 이전';
 else if(!d)state='작성일 미확인';
 else if(evidence)state='실사용 근거 확인 후보';
 const hits=state==='실사용 근거 확인 후보'?patterns.filter(([,re])=>re.test(evidence)): [];
 checked.set(r.row['링크'],{'원문 상태':state,'원문 작성일':d,'원문 발췌':body.slice(0,280),'실사용 근거':evidence?.slice(0,500)||'','집계 유형':hits.map(([label])=>label).join(' / ')});
}
const cases=prior.cases.map(r=>({...r,...(checked.get(r['링크'])||{'원문 상태':'수집 범위 밖 또는 요청 한도'})}));
const valid=cases.filter(r=>r['검색어'].startsWith('일반')&&r['원문 상태']==='실사용 근거 확인 후보');
const summary=[];
const put=(항목,건수,비율,설명)=>summary.push({항목,건수,비율,설명});
put('일반 후기 실사용 근거 확인 후보 (분모)',valid.length,'','원문 작성일과 작성자 본인의 LG 광파오븐 사용 근거가 자동 규칙에 일치한 일반 후기만 포함. 사람 검증 전 잠정치.');
for(const [label]of patterns){
 const count=valid.filter(r=>r['집계 유형'].split(' / ').includes(label)).length;
 put(label,count,valid.length?(100*count/valid.length).toFixed(1)+'%':'계산 불가','실사용 근거 문장 내 표현 일치. 중복 유형 가능.');
}
for(const [label,list] of [['일반',cases.filter(r=>r['검색어'].startsWith('일반'))],['유형 탐색',cases.filter(r=>!r['검색어'].startsWith('일반'))]]){
 const counts={};for(const r of list)counts[r['원문 상태']]=(counts[r['원문 상태']]||0)+1;
 for(const [state,count]of Object.entries(counts))put(label+' · '+state,count,'','유형 탐색 글은 분모에 포함하지 않음.');
}
for(const r of prior.summary.filter(r=>/^(Google|네이버|기간 이전)/.test(r.항목)))summary.push(r);
const review=cases.filter(r=>checked.has(r['링크'])).map(r=>Object.fromEntries(
 ['원문 작성일','출처','제목·영상','링크','검색어','원문 상태','실사용 근거','집계 유형','원문 발췌','최종 검토','최종 유형'].map(k=>[k,r[k]||''])
));
return [{json:{cases:review,summary,collected_at:prior.collected_at}}];
